import asyncio, json, hmac, hashlib, urllib.request, time
from playwright.async_api import async_playwright
B='http://localhost:3123'; O='/home/claude/e2e/'; LOG=[]
def log(*a): LOG.append(' '.join(str(x) for x in a)); print(*a, flush=True)
async def shot(pg, name): await pg.wait_for_timeout(500); await pg.screenshot(path=O+name+'.png')
async def api(pg, method, url, body=None, headers=None):
    return await pg.evaluate("([m,u,b,h])=>fetch(u,{method:m,headers:Object.assign({'Content-Type':'application/json'},h||{}),body:b}).then(async r=>({s:r.status,j:await r.json().catch(()=>null)}))", [method, url, json.dumps(body) if body is not None else None, headers])
async def login(pg, email, pw):
    await pg.goto(B+'/login'); await pg.wait_for_timeout(1200)
    await pg.fill('input[type=email]', email); await pg.fill('input[type=password]', pw)
    await pg.click('button[type=submit]'); await pg.wait_for_url('**/dashboard', timeout=15000); await pg.wait_for_timeout(2500)
async def logout(pg):
    await pg.locator('aside button[aria-label="Sign out"]').click(); await pg.wait_for_url('**/login**', timeout=15000)
async def nav(pg, name): await pg.locator(f'aside nav button:has-text("{name}")').click(); await pg.wait_for_timeout(1300)

