        big=await api(pg,'POST','/api/orders',{'customer':{'name':'QuickKart'},'items':[{'product_id':[x for x in (await api(pg,'GET','/api/products'))['j']['products'] if x['name'].startswith('Stretch')][0]['id'],'qty':500}]},{'Idempotency-Key':'e2e-big-order-1'})
        bid=big['j']['order']['id']; await api(pg,'PATCH','/api/orders',{'id':bid,'action':'transport','ewb_number':'341099998888','vehicle_number':'MH14XY4321'}); await pg.reload(); await pg.wait_for_timeout(2500); await nav(pg,'Orders')
