        urllib.request.urlopen(urllib.request.Request(B+'/api/whatsapp/webhook', data=lb.encode(), headers={'content-type':'application/json','x-hub-signature-256':'sha256='+hmac.new(b'e2e-app-secret', lb.encode(), hashlib.sha256).hexdigest()}, method='POST'))
